(function ($) {

$.fn.alterClass = function ( removals, additions ) {
	"use strict";
	var self = this;
	
	if ( removals.indexOf( '*' ) === -1 ) {
		// Use native jQuery methods if there is no wildcard matching
		self.removeClass( removals );
		return !additions ? self : self.addClass( additions );
	}
 
	var patt = new RegExp( '\\s' + 
			removals.
				replace( /\*/g, '[A-Za-z0-9-_]+' ).
				split( ' ' ).
				join( '\\s|\\s' ) + 
			'\\s', 'g' );
 
	self.each( function ( i, it ) {
		var cn = ' ' + it.className + ' ';
		while ( patt.test( cn ) ) {
			cn = cn.replace( patt, ' ' );
		}
		it.className = $.trim( cn );
	});
 
	return !additions ? self : self.addClass( additions );
};
 
})( jQuery );

//Taken from http://www.jacklmoore.com/notes/naturalwidth-and-naturalheight-in-ie/ on 1/7/2014
//There was no license and copyright information on the site on 1/7/2014

// adds .naturalWidth() and .naturalHeight() methods to jQuery
// for retreaving a normalized naturalWidth and naturalHeight.
(function ($) {
    "use strict";
    var
        props = ['Width', 'Height'],
        prop;

    while (prop = props.pop()) {
        (function (natural, prop) {
            $.fn[natural] = (natural in new Image()) ? 
            function () {
                return this[0][natural];
            } : 
            function () {
                var 
                node = this[0],
                img,
                value;

                if (node.tagName.toLowerCase() === 'img') {
                    img = new Image();
                    img.src = node.src,
                    value = img[prop];
                }
                return value;
            };
        }('natural' + prop, prop.toLowerCase()));
    }
}(jQuery));

//Taken from http://james.padolsey.com/javascript/get-document-height-cross-browser/ on 1/7/2014
//There was no license and copyright information on the site on 1/7/2014

$.getDocHeight = function(){
    return Math.min(
        $(document).height(),
        $(window).height()
    );
};

$.getDocWidth = function(){
    return Math.min(
        $(document).width(),
        $(window).width()
    );
};

/*jslint browser: true, regexp: true */

// Note: it is recommended to test this code with JSLint:
//
// http://www.jslint.com/
//
// You will need to indicate that the following global variables are already
// defined:
//
/*global $:true, Modernizr:true,  whLoad:true,  suitehelp:true, unescape:true, escape:true */

//Suitehelp feature flags
suitehelp.autoCloseTOC = false;
suitehelp.andSearch = true;
suitehelp.customizeRootBreadCrumb = false;
suitehelp.disablePrevAndNextButtons = false;

suitehelp.tocArray = suitehelp.leftbarContent.tocArray;
suitehelp.tocObject = {};

//Attach the approot to the relative urls to make absolute urls.
suitehelp.addApproot = function (t) {
    "use strict";

    var approot = $("head").attr("data-approot");
    return t.replace(/%APPROOT%/g, approot);
};

//Add html content to the DOM.
suitehelp.addContent = function (name, content) {
    "use strict";

    $("#" + name).html(suitehelp.makeAbsoluteURLs(document.location.href, suitehelp.addApproot(content)));
};

// Add a ?q=searchterm query string to a URL.
suitehelp.addQueryStringToURL = function (url, key, value) {
    "use strict";

    if (url.match(/\?/)) {
        url += "&";
    } else {
        url += "?";
    }

    return url + encodeURIComponent(key) + "=" + encodeURIComponent(value);
};

// Update the contents of the breadcrumbs div with the ancestors of the given topic ID
suitehelp.breadcrumbs = function () {
    "use strict";

    var $breadcrumbs = $("#breadcrumbs"),
        crumbs = [],
        $currLi = $('[id="toc-' + suitehelp.currid + '" ]'),
        $currLink = $currLi.children("a");

    $currLink.parents("li").each(function () {
        var $liLink = $(this),
            $alink = $liLink.children("a"),
            href = $alink.attr("href"),
            title;

        /*BreadCrumbs use <div> and not <span> to accomodate Bootstrap responsive design*/
        if (href) {
            /*The page was a topicref*/
            title = $.trim($alink.text().replace(/</g, "&lt;").replace(/>/g, "&gt;"));
            crumbs.unshift(" <a class='btn btn-default crumb' data-suitehelp-page='internal' href='" + href + "' title='" + title + "'><div>" + title + "</div></a>");

        } else {
            /*The page was a topicgroup*/
            title = $liLink.children("span").text().replace(/</g, "&lt;").replace(/>/g, "&gt;");
            crumbs.unshift(" <a class='btn btn-default crumb' title='" + title + "'><div>" + title + "</div></a>");
        }
    });

    //Only remove the dynamic breadcrumbs
    //Keep the home breadcrumb in classic and bootstrap. Keep the ellipse for bootstrap.
    $breadcrumbs.children("*:nth-child(n+" + suitehelp.breadCrumbPos + ")").remove();
    suitehelp.setRootOfBreadCrumbs();
    $breadcrumbs.append(crumbs.join(""));
    $breadcrumbs.find("a:last-child").addClass("current-breadcrumb");

    $("#leftbar").find("nav li.current").removeClass("current");
    $currLi.addClass("current");
    $('[id="search-' + suitehelp.currid + '"]').addClass("current");

    // If requested, close all other branches in the TOC
    if (suitehelp.autoCloseTOC) {
        suitehelp.closeOpenTrees($currLi);
    }

    // Open all parent nodes
    suitehelp.openTreeForCurElement();
};

//Check to see if the web server search is enabled.
suitehelp.callCheckSearch = function (val) {
    'use strict';

    $.ajax({
        data: {check: "search"},
        datatype: "json",
        success: function (data) {
            if ($.type(data) === "object" && data.search === true) {
                suitehelp.checkSearch = data.search;
                suitehelp.callWebSearch(val);
            } else {
                suitehelp.checkSearch = false;
                suitehelp.processSearchResults(suitehelp.simpleSearch(val));
            }
        },
        error: function () {
            suitehelp.checkSearch = false;
            suitehelp.processSearchResults(suitehelp.simpleSearch(val));
        }
    });
};
suitehelp.updateSearchUrls = function () {
    "use strict";
    $.each(suitehelp.untoc,
           function (key, value) {
            if (value.url !== undefined) {
                value.url = suitehelp.makeAbsoluteSingleUrl(document.location.href, suitehelp.addApproot(value.url));
            }
        });
};
suitehelp.makeAbsoluteSingleUrl = function (path, url) {
    "use strict";
    path = path || "";
    url = url || "";
    var relPath = path.replace(/#.*$/, '').replace(/\/[^\/]+$/, '/');
    return relPath + url;
};
//Call the web server search.
suitehelp.callWebSearch = function (val) {
    'use strict';

    $.ajax({
        data: {q : val},
        datatype: "json",
        success: function (data) {
            suitehelp.processSearchResults(data);
        },
        error: function () {
            suitehelp.processSearchResults(suitehelp.simpleSearch(val));
        }
    });
};

suitehelp.changeAudience = function (clicked) {
    "use strict";

    var audience = $("#audience_selector").val(),
        elementhref,
        test,
        toccount;
    $("#toc_nav li").each(function () {
        $("#" + this.id).removeClass("hideaudience").removeClass("tempLeaf");
        //only one instance of selAudience should exist
        elementhref =  $("#" + this.id + "> a").attr("href").replace(/\?selAudience=[^#]*/, "") + "?selAudience=" + audience;
        $("#" + this.id + "> a").attr("href", elementhref);
    });
    if (audience !== "ALL") {
        test = $('#toc_nav li').not('[data-audience~="' + $("#audience_selector").val() + '"]');
        test.each(function () {
            $("#" + this.id).addClass("hideaudience");
        });
        if (clicked) {
            $("#toc-" + suitehelp.currid).parents("li").andSelf().removeClass("hideaudience");
            $("#toc_nav li.open, #toc_nav li.closed").not('[class~="hideaudience"]').each(function () {
                if ($("#" + this.id + " li").not('[class~="hideaudience"]').length === 0) {
                    $("#" + this.id).addClass("tempLeaf");
                }
            });
        }
    }
    suitehelp.tocArray.length = 0;
    suitehelp.tocObject = {};
    toccount = 0;
    $('#toc_nav li').not('[class~="hideaudience"]').each(function () {
        suitehelp.tocArray[toccount] = $(this).attr("id").replace(/toc-/g, "");
        suitehelp.tocObject[$(this).attr("id").replace(/toc-/g, "")] = toccount;
        toccount = toccount + 1;
    });
};

// Determine if Ajax is supported by the current browser on the current page
// by making an asynchronous Ajax call.
// This function is passed two callbacks: one to be performed if Ajax is 
// available, a second to be called if Ajax is not available.
suitehelp.checkAjax = function (withAjax, withoutAjax) {
    "use strict";

    function go(x) {
        suitehelp.hasAjax = x;
        (x ? withAjax : withoutAjax)();
    }

    if (suitehelp.getQueryString("q") || suitehelp.getQueryString("local")) {
        suitehelp.hasAjax = false;
    }

    // Cache the result in the suitehelp object so that only one Ajax call
    // needs be performed. Initially, this value will be undefined. Check for
    // strict equality against true and false to determine if a cached answer
    // is present.
    if (suitehelp.hasAjax === true) {
        withAjax();
    } else if (suitehelp.hasAjax === false) {
        withoutAjax();
    } else {
        // No cache available. Try to load up an arbitrary page from the TOC
        // via Ajax. We need to ensure that the page we are trying to load is
        // not the current page, since most implementations will allow an Ajax
        // load for the current page even if other Ajax loads are disallowed.
        var links = $("#toc_nav a[href]"),
            stringLoc = (document.location.href).match(/[^\?]*/)[0],
            // Initial URL to try. If there are no links found in the TOC,
            // try loading the current page.
            url = stringLoc,
            i;
        for (i = 0; i < links.length; i += 1) {
            url = links[i].toString();
            if (url !== stringLoc) {
                break;
            }
        }
        $.ajax({
            url: url,
            success: function (data) {
                // Check that AJAX works by making sure that the data
                // is a string.  This will catch the case of Firefox responding
                // with an empty object in data when running from a filesystem.
                go(typeof data === "string");
            },
            error: function () {
                go(false);
            }
        });
    }
};

// Check for a context-sensitive link and redirect if present (and valid)
suitehelp.checkContext = function () {
    "use strict";

    var context = suitehelp.contexts[suitehelp.getQueryString("context")],
        adjustedQS =  window.location.search.substring(1).replace(/context=[^&]+&|(&|^)context=[^&]+/, "");
    if (context) {
        if (adjustedQS) {
            document.location = $("head").attr("data-approot") + context + "?" + adjustedQS;
        } else {
            document.location = $("head").attr("data-approot") + context;
        }
    }

};

suitehelp.checkScroll = function () {
    "use strict";

    var scroll;
    function getScrollValue(key) {
        suitehelp.queryString = {};
        var query = window.location.search.substring(1),
            vars,
            i,
            pair,
            hash;
        if (!query) {
            hash = window.location.hash;
            query = hash.slice(hash.indexOf('?') + 1);
        }
        vars = query.split("&");
        for (i = 0; i < vars.length; i += 1) {
            pair = vars[i].split("=");
            suitehelp.queryString[pair[0]] = unescape(pair[1]);
        }
        return suitehelp.queryString[key];
    }
    scroll = getScrollValue("scroll");
    if (scroll) {
        $("#" + scroll)[0].scrollIntoView();
    } else {
        $("article").scrollTop(0);
        if (suitehelp.customScrollBar) {
            (suitehelp.centerScroll).data('jsp').scrollTo(1, 1);
        }
    }
};

// Lookup a query string variable
suitehelp.getQueryString = function (key) {
    "use strict";

    if (!suitehelp.queryString) {
        suitehelp.queryString = {};
        var query = window.location.search.substring(1),
            vars = query.split("&"),
            i,
            pair;
        for (i = 0; i < vars.length; i += 1) {
            pair = vars[i].split("=");
            suitehelp.queryString[pair[0]] = unescape(pair[1]);
        }
    }

    return suitehelp.queryString[key];
};

suitehelp.getDialogTitle = function (img) {
    "use strict";

    var dialogTitle = "";
    //DitatOT Mode
    dialogTitle = img.parent(".fig").find(".figcap").text();

    if (dialogTitle === "") {
        //NativeMode standard figure
        dialogTitle = img.parent(".figure").find(".figcap").text();
    }
    if (dialogTitle === "") {
        //NativeMode Html5
        dialogTitle = img.parent("figure").find("figcaption").text();
    }
    return dialogTitle;
};

suitehelp.unhighlight = function () {
    "use strict";
    $("article").unhighlight({className: 'search_term'});
};

suitehelp.highlight = function () {
    "use strict";

    //Split out words and phrases ( series of words surrounded by quotes")
    var terms,
        term,
        termsOnly,
        searchInput = $("#search_textbox").val(),
        $article = $("article");

    if (searchInput !== "") {
        if (suitehelp.checkSearch) {
            termsOnly = searchInput.replace(/\s(NOT|AND|OR|NEAR|NEAR\/\d+)\s/g, " ");
            //splits words by spaces but will not split up a section in quotes
            terms = termsOnly.toLowerCase().replace(/^\s+|\s+$/g, '').match(/([^"\s]+)|("([^"]+)")/g);
        } else {
            terms = searchInput.toLowerCase().replace(/^\s+|\s+$/g, '').split(" ");
        }
        // Remove highlighting of the terms   
        suitehelp.unhighlight();
        if (terms) {
            while (terms.length) {
                term = terms.pop();
                // sanitize any special regex characters
                // term = term.replace(/([\[\\\^\$\.\|\?\*\+\(\)])/g, "\\$1"); Mantis 10108
                //remove leading and trailing quotes and trailing star
                term = term.replace(/^"/g, "").replace(/"$/g, "").replace(/\*$/g, "");
                if (term.length <= 3) {
                    $article.highlight(term, { wordsOnly: true, className: 'search_term' });
                } else {
                    $article.highlight(term, { className: 'search_term' });
                }
            }
        }
    }
};

// Switch "closed" to "open" as necessary, based on supplied current ID
suitehelp.openTreeForCurElement = function () {
    "use strict";

    $('[id="toc-' + suitehelp.currid + '" ]').parents("li").addBack().filter(".closed").toggleClass("open").toggleClass("closed");
};

suitehelp.loadChildrenForPrintAll = function (top, dest, andThen) {
    "use strict";

    var firstLi = top.children("ul").children("li").first(),
        id,
        contentHtml,
        href;

    function go(li) {
        if (li.length === 0) {
            return andThen();
        }

        id = li.attr("id");
        dest.append("<div id='printall-" + id + "'/>");
        href = li.children("a").attr("href");

        //If li is a topicgroup with no page reference, don't make ajax call
        if (!href) {
            suitehelp.loadChildrenForPrintAll(li, $("#printall-" + id), function () {
                go(li.next("li"));
            });
            return;
        }

        //First resolve all urls before loading data for printing
        $.ajax({
            url: href,
            success: function (data) {
                // Replace all relative URLs with absolute URLs
                data = suitehelp.makeAbsoluteURLs(li.children("a").attr("href"), data);
                contentHtml = $(data).find("article").html();

                $('[id="printall-' + id + '"]').html(contentHtml);
                suitehelp.loadChildrenForPrintAll(li,  $('[id="printall-' + id + '"]'), function () {
                    go(li.next("li"));
                });
            }
        });
    }
    go(firstLi);
};

//Load the index content.  
suitehelp.loadIndex = function () {
    "use strict";

    if (suitehelp.showIndex) {
        if ($("#index_nav").length) { //if it is in body.hamlet
            suitehelp.addContent("index_nav", suitehelp.indexBarContent.index);
            if ($("#index_nav li").length) { //if something loaded
                $("#index_container").show();
            }
        }
    }
};

